create table if not exists public.workspace_preferences (workspace_id uuid primary key references public.workspaces(id) on delete cascade, audience text[] not null default '{}', voice_preferences jsonb not null default '{}', publishing_preferences jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.workspace_preferences enable row level security; drop policy if exists workspace_preferences_member_read on public.workspace_preferences; create policy workspace_preferences_member_read on public.workspace_preferences for select to authenticated using (public.is_curatia_member(workspace_id));
